def task_func(file_path1, file_path2, delimiter=',', quotechar='"'):
    # Read the first file
    try:
        with open(file_path1, 'r', newline='') as f1:
            lines1 = f1.readlines()
    except FileNotFoundError:
        raise FileNotFoundError(f"File not found: {file_path1}")
    except Exception as e:
        raise Exception(f"Error reading file {file_path1}: {e}")

    # Read the second file
    try:
        with open(file_path2, 'r', newline='') as f2:
            lines2 = f2.readlines()
    except FileNotFoundError:
        raise FileNotFoundError(f"File not found: {file_path2}")
    except Exception as e:
        raise Exception(f"Error reading file {file_path2}: {e}")

    # Check if either file is empty
    if not lines1:
        raise ValueError(f"File {file_path1} is empty")
    if not lines2:
        raise ValueError(f"File {file_path2} is empty")

    # Use ndiff to compare the two lists of lines
    diff = list(ndiff(lines1, lines2))

    # Build the report
    line_number = 0
    report = []

    for item in diff:
        if item.startswith(' '):
            # No change
            line_number += 1
            report.append({
                'Line Number': line_number,
                'Status': ' ',
                'Content': item[1:].rstrip('\n\r')
            })
        elif item.startswith('-'):
            # Line present in first file but not in second
            line_number += 1
            report.append({
                'Line Number': line_number,
                'Status': '-',
                'Content': item[1:].rstrip('\n\r')
            })
        elif item.startswith('+'):
            # Line present in second file but not in first
            # Line number stays the same as the previous line in file1 context
            # Actually, ndiff doesn't track line numbers directly. We need to handle this carefully.
            # For '+' lines, they don't correspond to a line in file1, so we might want to use the current line_number
            # But typically, for a unified diff-like view, '+' lines are shown at the position where they would be inserted.
            # Let's keep the line_number as is (it represents the position in file1)
            report.append({
                'Line Number': line_number,
                'Status': '+',
                'Content': item[1:].rstrip('\n\r')
            })
        elif item.startswith('?'):
            # This is a hint line from ndiff, we can skip it or handle it
            # ndiff with default settings shouldn't produce '?' lines unless we're using a different mode
            # Actually, ndiff can produce '?' lines for character-level differences, but we're comparing lines
            # Let's skip them
            continue

    # Create DataFrame
    if report:
        df = pd.DataFrame(report, columns=['Line Number', 'Status', 'Content'])
    else:
        df = pd.DataFrame(columns=['Line Number', 'Status', 'Content'])

    return df

